package com.sora.splineroads.client;
import com.sora.splineroads.SplineRoads;import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;import com.sora.splineroads.world.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.registries.Registries;import net.minecraft.world.Difficulty;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.WorldOptions;import net.minecraft.world.level.levelgen.presets.WorldPresets;
import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=SplineRoads.ID,value=Dist.CLIENT)
public final class Stack201NativeVisual {
 private static final Path OUT=Path.of("feedback201-stack");private static boolean started,done;private static int stage,ticks,ready;private static long deadline;private static CompletableFuture<Stack201VisualFixture.Scene> pending;private static Stack201VisualFixture.Scene scene;
 private static Object field(Object target,String name)throws Exception{var f=(target instanceof Class<?> c?c:target.getClass()).getDeclaredField(name);f.setAccessible(true);return f.get(target instanceof Class<?>?null:target);}
 private static net.minecraft.server.level.ServerPlayer player(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());}
 private static net.minecraft.world.level.levelgen.WorldDimensions dimensions(net.minecraft.core.RegistryAccess r){var flat=net.minecraft.world.level.levelgen.flat.FlatLevelGeneratorSettings.getDefault(r.registryOrThrow(Registries.BIOME).asLookup(),r.registryOrThrow(Registries.STRUCTURE_SET).asLookup(),r.registryOrThrow(Registries.PLACED_FEATURE).asLookup());return r.registryOrThrow(Registries.WORLD_PRESET).getOrThrow(WorldPresets.FLAT).createWorldDimensions().replaceOverworldGenerator(r,new net.minecraft.world.level.levelgen.FlatLevelSource(flat));}
 private static void camera(Minecraft mc,V eye,V at){var d=at.sub(eye);float yaw=(float)RoadPlanner.yaw(d),pitch=(float)-Math.toDegrees(Math.atan2(d.y(),d.horizontalLength()));mc.getSingleplayerServer().execute(()->{var p=player(mc);p.getAbilities().flying=true;p.setNoGravity(true);p.onUpdateAbilities();p.teleportTo(p.serverLevel(),eye.x(),eye.y(),eye.z(),yaw,pitch);});mc.player.setPos(eye.x(),eye.y(),eye.z());mc.player.setYRot(yaw);mc.player.yRotO=yaw;mc.player.setXRot(pitch);mc.player.xRotO=pitch;}
 private static boolean settled()throws Exception{if(!((Map<?,?>)field(RoadRenderer.class,"jobs")).isEmpty()||field(RoadRenderer.class,"pendingUpload")!=null||SmartSignClient.pendingUploads())return false;for(var section:(List<?>)field(RoadRenderer.class,"visible"))if((Boolean)field(section,"dirty")&&RoadTerrainModels.regionLoaded((RoadRenderMesh.Section)field(section,"key")))return false;return true;}
 private static void shot(Minecraft mc,String name)throws Exception{try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(OUT.resolve(name+".png"));}System.out.println("SR201 STACK CAPTURE "+name);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(!Boolean.getBoolean("road.stack201Visual")||done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();ticks++;
  try{
   if(!started){if(!(mc.screen instanceof TitleScreen)||mc.getOverlay()!=null)return;started=true;Files.createDirectories(OUT);deadline=System.nanoTime()+1_200_000_000_000L;mc.getTutorial().setStep(net.minecraft.client.tutorial.TutorialSteps.NONE);mc.options.pauseOnLostFocus=false;mc.options.enableVsync().set(false);mc.options.renderDistance().set(16);mc.options.framerateLimit().set(60);mc.options.cloudStatus().set(CloudStatus.OFF);mc.options.fov().set(95);mc.createWorldOpenFlows().createFreshLevel("sr201-stack-"+System.currentTimeMillis(),new LevelSettings("SR201 isolated STACK",GameType.CREATIVE,false,Difficulty.PEACEFUL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(201,false,false),Stack201NativeVisual::dimensions);return;}
   if(System.nanoTime()>deadline)throw new AssertionError("timeout stage="+stage);if(mc.level==null||mc.player==null||mc.getOverlay()!=null||ticks<ready)return;mc.player.setDeltaMovement(0,0,0);mc.player.getAbilities().flying=true;mc.player.setNoGravity(true);
   if(stage==0){mc.setScreen(null);mc.options.hideGui=true;pending=mc.getSingleplayerServer().submit(()->{var p=player(mc);p.setGameMode(GameType.CREATIVE);p.serverLevel().setDayTime(6000);p.serverLevel().setWeatherParameters(6000,0,false,false);return Stack201VisualFixture.create(p);});stage=1;return;}
   if(stage==1){if(!pending.isDone())return;scene=pending.join();mc.options.fov().set(110);camera(mc,new V(0,scene.ground()+180,0),new V(.001,scene.ground(),0));stage=2;ready=ticks+240;return;}
   if(stage==2){if(!ClientRoads.INDEX.roads.keySet().containsAll(scene.centralRoads())||!settled()||(Integer)field(RoadRenderer.class,"lastDraws")<=0)return;System.out.println("SR201 STACK OVERVIEW visible="+((List<?>)field(RoadRenderer.class,"visible")).size()+" draws="+field(RoadRenderer.class,"lastDraws")+" centralRecords="+scene.centralRoads().size()+" received="+ClientRoads.INDEX.roads.size());shot(mc,"01-stack-central-overview");mc.options.fov().set(70);camera(mc,scene.nose().add(new V(-8,5,12)),scene.nose().add(new V(0,.8,0)));stage=3;ready=ticks+220;return;}
   if(stage==3){if(!ClientRoads.INDEX.roads.containsKey(scene.feed())||!settled())return;shot(mc,"02-shared-feed-nose-rail");camera(mc,scene.guide().add(new V(-20,13,15)),scene.guide().add(new V(0,.1,0)));stage=4;ready=ticks+160;return;}
   if(stage==4){if(!settled())return;shot(mc,"03-shared-feed-guide-dashes");Files.writeString(OUT.resolve("passed.txt"),"PASS actual server STACK transaction with "+scene.roads().size()+" saved assembly roads; all "+scene.centralRoads().size()+" central-road records independently received for overview, then actual shared-feed record received at close view. Settled native central overview has positive draw calls. Full distant endpoints lie outside overview; visual findings require screenshot inspection.\n"+scene);System.out.println("SR201 STACK NATIVE PASS");done=true;mc.stop();}
  }catch(Throwable failure){done=true;failure.printStackTrace();try{Files.writeString(OUT.resolve("failure.txt"),"stage="+stage+" "+failure);}catch(Exception ignored){}mc.stop();}
 }
}
